package com.bitedash.dto; import com.bitedash.entity.*; import java.math.*; import java.time.*; import java.util.*; public record OrderResponse(Long id,String deliveryAddress,BigDecimal totalAmount,OrderStatus status,LocalDateTime orderedAt,List<Item> items){public record Item(Long foodItemId,String name,int quantity,BigDecimal unitPrice){} public static OrderResponse of(Order o){return new OrderResponse(o.getId(),o.getDeliveryAddress(),o.getTotalAmount(),o.getStatus(),o.getOrderedAt(),o.getItems().stream().map(i->new Item(i.getFoodItem().getId(),i.getFoodItem().getName(),i.getQuantity(),i.getUnitPrice())).toList());}}
